        1 DUPTABLE                         R0 K10 [{[1] = "--!nocheck\n--[[\n\tAnimate — loads and plays the animation graph for this character.\n\n\tThis script is configured through attributes set by the Animation Graph Editor:\n\t  • GraphName / CharacterName / SourceAssetId — identify the graph to play.\n\t  • IsServerAuthority — whether the place used Server Authority when the scripts were created.\n\t  • PreviewInStudio — when true (the default), Studio play-testing loads the unpublished graph\n\t    locally so you can iterate without publishing. Toggle this attribute OFF to test the\n\t    PUBLISHED asset (SourceAssetId) in Studio instead.\n]]\nlocal RunService = game:GetService(\"RunService\")\n\nlocal module = {}\n\nlocal getGraphMetadata\nlocal resolveServerPreviewClip\nlocal resolveClientPreviewClip\n\n-- Loads and plays a local, unpublished animation graph during Studio play-testing.\n-- On the client (player characters): uses the clone staged into ReplicatedStorage.\n-- On the server (NPCs): registers the graph directly from ServerStorage. This only renders in\n-- single-player Studio play, where the server and client share one process.\n-- This block can be removed when publishing your game.\nfunction module.setupPreview(character: Model?)\n\tcharacter = character or script.Parent\n\tif not character or not character:IsA(\"Model\") then\n\t\treturn\n\tend\n\n\t-- RegisterAnimationClip is process-local, so an unpublished graph can't cross the\n\t-- client/server boundary that Server Authority relies on.\n\tif script:GetAttribute(\"IsServerAuthority\") then\n\t\twarn(\n\t\t\t\"This Animate script was created while Workspace.AuthorityMode was Server. \"\n\t\t\t\t.. \"Previewing an unpublished graph only works in Automatic mode — publish the graph, \"\n\t\t\t\t.. \"or recreate the Animate script in Automatic mode, to preview.\"\n\t\t)\n\tend\n\n\tlocal humanoid = character:WaitForChild(\"Humanoid\")\n\tlocal animator: Animator? = humanoid:FindFirstChildOfClass(\"Animator\")\n\tif not animator then\n\t\tif RunService:IsServer() then\n\t\t\tanimator = Instance.new(\"Animator\")\n\t\t\tanimator.Name = \"Animator\"\n\t\t\tanimator.Parent = humanoid\n\t\telse\n\t\t\tanimator = humanoid:WaitForChild(\"Animator\")\n\t\t\tassert(animator:IsA(\"Animator\"), \"Animator is not an Animator\")\n\t\tend\n\tend\n\n\tif not animator then\n\t\twarn(\"Animator not found\")\n\t\treturn\n\tend\n\n\tlocal graphName, characterName = getGraphMetadata()\n\tif not graphName or graphName == \"\" or not characterName or characterName == \"\" then\n\t\twarn(\"Missing GraphName or CharacterName for Studio preview\")\n\t\treturn\n\tend\n\n\tlocal graphAssetId\n\tif RunService:IsServer() then\n\t\tgraphAssetId = resolveServerPreviewClip(graphName, characterName)\n\telse\n\t\tgraphAssetId = resolveClientPreviewClip(graphName, characterName)\n\tend\n\tif not graphAssetId then\n\t\treturn\n\tend\n\n\tlocal animation = Instance.new(\"Animation\")\n\tanimation.AnimationId = graphAssetId\n\tanimation:AddTag(\"AnimationEditor_GraphAnimation\")\n\tanimation.Parent = script\n\n\tlocal track = animator:LoadAnimation(animation)\n\ttrack:Play()\n\n\t-- Set graph parameters each frame (uncomment and edit as needed):\n\t-- RunService.Stepped:Connect(function()\n\t-- \ttrack:SetParameter(\"ParameterName\", value)\n\t-- end)\nend\n\n-- Loads and plays the animation graph using the SourceAssetId.\nfunction module.setup(character: Model?)\n\tcharacter = character or script.Parent\n\tif not character or not character:IsA(\"Model\") then\n\t\treturn\n\tend\n\n\tlocal humanoid = character:WaitForChild(\"Humanoid\")\n\tlocal animator = humanoid:FindFirstChildOfClass(\"Animator\")\n\tif not animator then\n\t\tif RunService:IsServer() then\n\t\t\tanimator = Instance.new(\"Animator\")\n\t\t\tanimator.Name = \"Animator\"\n\t\t\tanimator.Parent = humanoid\n\t\telse\n\t\t\tanimator = humanoid:WaitForChild(\"Animator\")\n\t\t\tassert(animator:IsA(\"Animator\"), \"Animator is not an Animator\")\n\t\tend\n\tend\n\n\tif not animator then\n\t\twarn(\"Animator not found\")\n\t\treturn\n\tend\n\n\tlocal sourceAssetId = script:GetAttribute(\"SourceAssetId\")\n\tif not sourceAssetId or sourceAssetId == \"\" then\n\t\treturn\n\tend\n\n\tlocal graphAssetId = `rbxassetid://{sourceAssetId}`\n\tlocal animation = Instance.new(\"Animation\")\n\tanimation.AnimationId = graphAssetId\n\tanimation:AddTag(\"AnimationEditor_GraphAnimation\")\n\tanimation.Parent = script\n\n\tlocal function findGraphTrack(): AnimationTrack?\n\t\tfor _, track in animator:GetPlayingAnimationTracks() do\n\t\t\tif track.Animation and track.Animation.AnimationId == graphAssetId then\n\t\t\t\treturn track\n\t\t\tend\n\t\tend\n\t\treturn nil\n\tend\n\n\tlocal bindConn = nil\n\tlocal function step()\n\t\tlocal track = findGraphTrack()\n\t\tif not track then\n\t\t\ttrack = animator:LoadAnimation(animation)\n\t\t\ttrack:Play()\n\t\tend\n\n\t\t-- Set graph parameters here:\n\t\t-- track:SetParameter(\"ParameterName\", value)\n\tend\n\tbindConn = RunService:BindToSimulation(step, Enum.StepFrequency.Hz60, 1999)\n\n\thumanoid.Died:Once(function()\n\t\tbindConn:Disconnect()\n\tend)\nend\n\n-- Helper functions\n\nfunction getGraphMetadata()\n\tlocal graphName = script:GetAttribute(\"GraphName\")\n\tlocal characterName = script:GetAttribute(\"CharacterName\")\n\treturn graphName, characterName\nend\n\nfunction resolveServerPreviewClip(graphName: string, characterName: string): string?\n\tlocal ServerStorage = game:GetService(\"ServerStorage\")\n\tlocal AnimationClipProvider = game:GetService(\"AnimationClipProvider\")\n\n\tlocal animSavesRoot = ServerStorage:FindFirstChild(\"RBX_ANIMSAVES\")\n\tlocal perCharSaves = animSavesRoot and animSavesRoot:FindFirstChild(characterName)\n\tlocal graphInstance = perCharSaves and perCharSaves:FindFirstChild(graphName)\n\tif not graphInstance then\n\t\twarn(`Graph \"{graphName}\" not found in ServerStorage.RBX_ANIMSAVES/{characterName}`)\n\t\treturn nil\n\tend\n\treturn AnimationClipProvider:RegisterAnimationClip(graphInstance)\nend\n\nfunction resolveClientPreviewClip(graphName: string, characterName: string): string?\n\tlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\tlocal AnimationClipProvider = game:GetService(\"AnimationClipProvider\")\n\tlocal editorFolder = ReplicatedStorage:WaitForChild(\"AnimationGraphEditor\", 30)\n\tif not editorFolder then\n\t\twarn(\"AnimationGraphEditor folder not found in ReplicatedStorage\")\n\t\treturn nil\n\tend\n\tlocal key = characterName .. \"_\" .. graphName\n\tlocal graphClone = editorFolder:WaitForChild(key, 30)\n\tif not graphClone then\n\t\twarn(`Graph clone \"{key}\" not found in ReplicatedStorage.AnimationGraphEditor`)\n\t\treturn nil\n\tend\n\treturn AnimationClipProvider:RegisterAnimationClip(graphClone)\nend\n\nreturn module\n", ["AnimateLegacy"] = "--!nocheck\nlocal AnimationClipProvider = game:GetService(\"AnimationClipProvider\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nif not RunService:IsRunning() then\n\treturn\nend\n\nlocal track = nil\n\n-- {{PARAMETERS}}\n\nlocal character = script.Parent\nlocal humanoid = character:WaitForChild(\"Humanoid\")\nlocal graphNameValue = script:FindFirstChild(\"GraphName\")\nlocal graphName = if graphNameValue then graphNameValue.Value else nil\nlocal characterNameValue = script:FindFirstChild(\"CharacterName\")\nlocal characterName = if characterNameValue then characterNameValue.Value else nil\n\nlocal editorFolder = nil\nlocal graphKey = nil\n\nif RunService:IsStudio() and characterName and graphName then\n\teditorFolder = ReplicatedStorage:WaitForChild(\"AnimationGraphEditor\", 1)\n\tgraphKey = characterName .. \"_\" .. graphName\nend\n\nlocal animator = humanoid:FindFirstChildOfClass(\"Animator\") or humanoid\n\nlocal animation = nil\nlocal lastAnimationId = nil\n\nlocal function stopCurrentAnimation()\n\tif track then\n\t\ttrack:Stop()\n\t\ttrack:Destroy()\n\t\ttrack = nil\n\tend\n\tif animation then\n\t\tanimation:Destroy()\n\t\tanimation = nil\n\tend\n\tlastAnimationId = nil\nend\n\nlocal function registerGraphClone()\n\tif not editorFolder or not graphKey then\n\t\treturn nil\n\tend\n\n\tlocal graphClone = editorFolder:FindFirstChild(graphKey)\n\tif not graphClone then\n\t\treturn nil\n\tend\n\n\treturn AnimationClipProvider:RegisterAnimationClip(graphClone)\nend\n\nlocal function resolveAnimationId()\n\tif not RunService:IsStudio() then\n\t\tlocal sourceAssetIdValue = script:FindFirstChild(\"SourceAssetId\")\n\t\tlocal sourceAssetId = if sourceAssetIdValue then sourceAssetIdValue.Value else nil\n\n\t\tif sourceAssetId and sourceAssetId ~= \"\" then\n\t\t\treturn `rbxassetid://{sourceAssetId}`\n\t\tend\n\t\treturn nil\n\tend\n\n\treturn registerGraphClone()\nend\n\nlocal function updatePlayState()\n\tlocal animationId = resolveAnimationId()\n\n\tif animationId and animationId ~= \"\" then\n\t\tif animationId ~= lastAnimationId then\n\t\t\tstopCurrentAnimation()\n\t\t\tanimation = Instance.new(\"Animation\")\n\t\t\tanimation.AnimationId = animationId\n\t\t\tanimation:AddTag(\"AnimationEditor_GraphAnimation\")\n\t\t\tanimation.Parent = script\n\t\t\ttrack = animator:LoadAnimation(animation)\n\t\t\ttrack:Play()\n\t\t\tlastAnimationId = animationId\n\t\tend\n\telse\n\t\tstopCurrentAnimation()\n\tend\nend\n\nupdatePlayState()\n\nif editorFolder and graphKey then\n\teditorFolder.ChildAdded:Connect(function(child)\n\t\tif child.Name == graphKey then\n\t\t\tupdatePlayState()\n\t\tend\n\tend)\nend\n", ["PreviewStaging"] = "--!nocheck\n-- Preview-only helper for the Animation Graph Editor.\n-- Stages unpublished animation graphs from ServerStorage into ReplicatedStorage so client\n-- scripts can load them during Studio play-testing. Does nothing in a published game.\n-- This script is safe to delete when publishing.\nlocal RunService = game:GetService(\"RunService\")\n\nif not RunService:IsStudio() then\n\treturn\nend\n\nlocal CollectionService = game:GetService(\"CollectionService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\n\nlocal animSavesRoot = ServerStorage:FindFirstChild(\"RBX_ANIMSAVES\")\nif not animSavesRoot then\n\treturn\nend\n\nlocal editorFolder = ReplicatedStorage:FindFirstChild(\"AnimationGraphEditor\")\nif not editorFolder then\n\tlocal newFolder = Instance.new(\"Folder\")\n\tnewFolder.Name = \"AnimationGraphEditor\"\n\tnewFolder.Parent = ReplicatedStorage\n\teditorFolder = newFolder\nend\n\nlocal clonedKeys = {}\nfor _, animateScript in CollectionService:GetTagged(\"AnimationEditor_AnimateScript\") do\n\tlocal graphName = animateScript:GetAttribute(\"GraphName\")\n\tlocal characterName = animateScript:GetAttribute(\"CharacterName\")\n\tif not graphName or graphName == \"\" or not characterName or characterName == \"\" then\n\t\tcontinue\n\tend\n\n\tlocal key = characterName .. \"_\" .. graphName\n\tif clonedKeys[key] then\n\t\tcontinue\n\tend\n\n\tlocal perCharSaves = animSavesRoot:FindFirstChild(characterName)\n\tlocal graphInstance = perCharSaves and perCharSaves:FindFirstChild(graphName)\n\tif not graphInstance then\n\t\tcontinue\n\tend\n\n\tlocal graphClone = graphInstance:Clone()\n\tgraphClone.Name = key\n\tgraphClone.Parent = editorFolder\n\tclonedKeys[key] = true\nend\n", ["RunClient"] = "--!nocheck\n-- Runs on all clients for the player character.\n-- During Studio play-testing (with the PreviewInStudio attribute enabled) the graph is loaded\n-- locally, ignoring Server Authority, since RegisterAnimationClip is process-local. Set the\n-- PreviewInStudio attribute to false to test the published asset in Studio instead.\n-- In a published game with Server Authority, the owning player enables prediction rollback.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal character = script.Parent.Parent\nlocal animate = require(script.Parent)\n\nif RunService:IsStudio() and script.Parent:GetAttribute(\"PreviewInStudio\") then\n\tanimate.setupPreview(character)\n\treturn\nend\n\nlocal isServerAuthority = script.Parent:GetAttribute(\"IsServerAuthority\")\nif isServerAuthority then\n\tlocal localPlayer = Players.LocalPlayer\n\tif localPlayer and localPlayer.Character == character then\n\t\tlocal humanoid = character:WaitForChild(\"Humanoid\")\n\t\tlocal animator = humanoid:FindFirstChildOfClass(\"Animator\")\n\t\tif animator then\n\t\t\tRunService:SetPredictionMode(animator, Enum.PredictionMode.On)\n\t\t\tRunService:SetPredictionMode(humanoid, Enum.PredictionMode.On)\n\t\tend\n\tend\nend\n\nanimate.setup(character)\n", ["RunServer"] = "--!nocheck\n-- Runs on the server: loads and plays the animation graph, which replicates to all clients.\nlocal RunService = game:GetService(\"RunService\")\n\nlocal character = script.Parent.Parent\n\nif RunService:IsStudio() and script.Parent:GetAttribute(\"PreviewInStudio\") then\n\t-- When a RunClient sibling exists (player character), the owning client renders the preview.\n\t-- Otherwise (NPC) preview on the server, which is visible in single-player Studio play.\n\tif script.Parent:FindFirstChild(\"RunClient\") then\n\t\treturn\n\tend\n\trequire(script.Parent).setupPreview(character)\n\treturn\nend\n\nrequire(script.Parent).setup(character)\n"}]
